package com.bank.escalation;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.logging.Logger;

// Produces the rightmost contact per escalation level.
public class RightViewService {

    private static final Logger log = Logger.getLogger(RightViewService.class.getName());

    public List<String> rightSideView(EscalationNode root) {
        List<String> result = new ArrayList<>();
        if (root == null) {
            return result;
        }
        Queue<EscalationNode> queue = new ArrayDeque<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            for (int i = 0; i < levelSize; i++) {
                EscalationNode node = queue.poll();
                // Last node in this level = rightmost visible from the right.
                if (i == levelSize - 1) {
                    result.add(node.getContact());
                }
                if (node.getLeft() != null) queue.offer(node.getLeft());
                if (node.getRight() != null) queue.offer(node.getRight());
            }
        }
        return result;
    }

    public List<String> emergencyContactSheet(EscalationNode root) {
        List<String> view = rightSideView(root);
        log.info(() -> "Emergency fallback contacts (right-side view) = " + view);
        return view;
    }
}
