package com.bank.escalation;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class RightViewDemo {

    private static final Logger log = Logger.getLogger(RightViewDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Escalation Right-Side View");

        //           CEO
        //          /    \
        //      RegionA  RegionB
        //        \          \
        //       DeskA2     DeskB2
        //        /
        //     ClerkA3   ← rightmost on its level is a LEFT node
        EscalationNode ceo = new EscalationNode("CEO");
        EscalationNode regionA = new EscalationNode("RegionA");
        EscalationNode regionB = new EscalationNode("RegionB");
        ceo.setLeft(regionA);
        ceo.setRight(regionB);
        regionA.setRight(new EscalationNode("DeskA2"));
        regionB.setRight(new EscalationNode("DeskB2"));
        regionA.getRight().setLeft(new EscalationNode("ClerkA3"));

        new RightViewService().emergencyContactSheet(ceo);
    }
}
